public int singleNumberII(int[] nums) {
    int ones = 0, twos = 0;
    for (int x : nums) {
        ones = (ones ^ x) & ~twos;
        twos = (twos ^ x) & ~ones;
    }
    return ones;
}

public int[] singleNumberIII(int[] nums) {
    int xorAll = 0;
    for (int x : nums) xorAll ^= x;
    int diff = xorAll & (-xorAll); // lowest set bit
    int a = 0, b = 0;
    for (int x : nums) {
        if ((x & diff) != 0) a ^= x;
        else b ^= x;
    }
    return new int[]{a, b};
}

public int findMaximumXOR(int[] nums) {
    int max = 0, mask = 0;
    for (int i = 31; i >= 0; i--) {
        mask |= (1 << i);
        java.util.Set<Integer> prefixes = new java.util.HashSet<>();
        for (int x : nums) prefixes.add(x & mask);
        int candidate = max | (1 << i);
        for (int p : prefixes) {
            if (prefixes.contains(candidate ^ p)) {
                max = candidate;
                break;
            }
        }
    }
    return max;
}

public int getSum(int a, int b) {
    while (b != 0) {
        int carry = (a & b) << 1;
        a = a ^ b;
        b = carry;
    }
    return a;
}

public int[] countBits(int n) {
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = dp[i >> 1] + (i & 1);
    }
    return dp;
}

public java.util.List<java.util.List<Integer>> subsets(int[] nums) {
    int n = nums.length;
    java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
    for (int mask = 0; mask < (1 << n); mask++) {
        java.util.List<Integer> sub = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) sub.add(nums[i]);
        }
        res.add(sub);
    }
    return res;
}

public int rangeBitwiseAnd(int left, int right) {
    int shift = 0;
    while (left < right) {
        left >>= 1;
        right >>= 1;
        shift++;
    }
    return left << shift;
}

public int minimumXORSum(int[] nums1, int[] nums2) {
    int n = nums1.length;
    int[] dp = new int[1 << n];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        if (dp[mask] == Integer.MAX_VALUE) continue;
        int i = Integer.bitCount(mask); // index into nums1
        for (int j = 0; j < n; j++) {
            if ((mask & (1 << j)) == 0) {
                int next = mask | (1 << j);
                dp[next] = Math.min(dp[next], dp[mask] + (nums1[i] ^ nums2[j]));
            }
        }
    }
    return dp[(1 << n) - 1];
}

public int countArrangement(int n) {
    int[] dp = new int[1 << n];
    dp[0] = 1;
    for (int mask = 0; mask < (1 << n); mask++) {
        if (dp[mask] == 0) continue;
        int pos = Integer.bitCount(mask) + 1; // 1-indexed position to fill
        for (int num = 1; num <= n; num++) {
            if ((mask & (1 << (num - 1))) == 0 && (num % pos == 0 || pos % num == 0)) {
                dp[mask | (1 << (num - 1))] += dp[mask];
            }
        }
    }
    return dp[(1 << n) - 1];
}

public boolean isPowerOfTwo(int n) {
    return n > 0 && (n & (n - 1)) == 0;
}

public boolean isPowerOfThree(int n) {
    // 1162261467 = 3^19, the largest power of 3 that fits in an int
    return n > 0 && 1162261467 % n == 0;
}

public boolean isPowerOfFour(int n) {
    // power of two, and its single set bit sits at an even position
    return n > 0 && (n & (n - 1)) == 0 && (n & 0x55555555) != 0;
}

public double myPow(double x, int n) {
    long N = n;
    if (N < 0) {
        x = 1 / x;
        N = -N;
    }
    double result = 1.0;
    while (N > 0) {
        if ((N & 1) == 1) result *= x;
        x *= x;
        N >>= 1;
    }
    return result;
}

public int mySqrt(int x) {
    if (x < 2) return x;
    long lo = 1, hi = x / 2;
    while (lo <= hi) {
        long mid = lo + (hi - lo) / 2;
        long sq = mid * mid;
        if (sq == x) return (int) mid;
        else if (sq < x) lo = mid + 1;
        else hi = mid - 1;
    }
    return (int) hi;   // largest mid with mid*mid <= x
}

public int titleToNumber(String columnTitle) {
    int result = 0;
    for (char c : columnTitle.toCharArray()) {
        result = result * 26 + (c - 'A' + 1);
    }
    return result;
}

public String convertToTitle(int columnNumber) {
    StringBuilder sb = new StringBuilder();
    while (columnNumber > 0) {
        columnNumber--;                       // shift to 0-based digit
        sb.append((char) ('A' + columnNumber % 26));
        columnNumber /= 26;
    }
    return sb.reverse().toString();
}

public int countPrimes(int n) {
    if (n < 3) return 0;
    boolean[] composite = new boolean[n];   // composite[k] == true means k is not prime
    int count = 0;
    for (int i = 2; i < n; i++) {
        if (!composite[i]) {
            count++;
            for (long j = (long) i * i; j < n; j += i) {
                composite[(int) j] = true;
            }
        }
    }
    return count;
}

public String fractionToDecimal(int numerator, int denominator) {
    if (numerator == 0) return "0";
    StringBuilder sb = new StringBuilder();
    if ((numerator < 0) ^ (denominator < 0)) sb.append('-');
    long num = Math.abs((long) numerator);
    long den = Math.abs((long) denominator);
    sb.append(num / den);
    long rem = num % den;
    if (rem == 0) return sb.toString();
    sb.append('.');
    Map<Long, Integer> seen = new HashMap<>();   // remainder -> index in sb
    while (rem != 0) {
        if (seen.containsKey(rem)) {
            int start = seen.get(rem);
            sb.insert(start, '(');
            sb.append(')');
            break;
        }
        seen.put(rem, sb.length());
        rem *= 10;
        sb.append(rem / den);
        rem %= den;
    }
    return sb.toString();
}

public int calculate(String s) {
    return helper(s, new int[]{0});
}
private int helper(String s, int[] i) {
    Deque<Integer> stack = new ArrayDeque<>();
    long num = 0;
    char op = '+';   // operator preceding the current number
    while (i[0] < s.length()) {
        char c = s.charAt(i[0]++);
        if (Character.isDigit(c)) {
            num = num * 10 + (c - '0');
        } else if (c == '(') {
            num = helper(s, i);   // value of the parenthesised block
        }
        boolean isOperator = (c != ' ' && !Character.isDigit(c));
        if (isOperator || i[0] == s.length()) {
            switch (op) {
                case '+': stack.push((int) num); break;
                case '-': stack.push((int) -num); break;
                case '*': stack.push(stack.pop() * (int) num); break;
                case '/': stack.push(stack.pop() / (int) num); break;
            }
            op = c;
            num = 0;
        }
        if (c == ')') break;   // finished this nested expression
    }
    int sum = 0;
    for (int v : stack) sum += v;
    return sum;
}

public int maxPoints(int[][] points) {
    int n = points.length;
    if (n <= 2) return n;
    int max = 1;
    for (int i = 0; i < n; i++) {
        Map<Long, Integer> slopes = new HashMap<>();
        int localMax = 0;
        for (int j = i + 1; j < n; j++) {
            int dx = points[j][0] - points[i][0];
            int dy = points[j][1] - points[i][1];
            int g = gcd(dx, dy);
            dx /= g; dy /= g;
            if (dx < 0 || (dx == 0 && dy < 0)) { dx = -dx; dy = -dy; }
            long key = ((long) dx << 20) | (dy & 0xFFFFF);
            int cnt = slopes.merge(key, 1, Integer::sum);
            localMax = Math.max(localMax, cnt);
        }
        max = Math.max(max, localMax + 1);
    }
    return max;
}
private int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

private static final int MOD = 1337;
public int superPow(int a, int[] b) {
    a %= MOD;
    int result = 1;
    for (int digit : b) {
        result = powMod(result, 10) * powMod(a, digit) % MOD;
    }
    return result;
}
private int powMod(int base, int exp) {
    base %= MOD;
    int res = 1;
    for (int i = 0; i < exp; i++) res = res * base % MOD;
    return res;
}

public int nthMagicalNumber(int n, int a, int b) {
    final int MOD = 1_000_000_007;
    long lcm = (long) a / gcd(a, b) * b;
    long lo = 1, hi = (long) Math.min(a, b) * n;
    while (lo < hi) {
        long mid = lo + (hi - lo) / 2;
        long count = mid / a + mid / b - mid / lcm;
        if (count < n) lo = mid + 1;
        else hi = mid;
    }
    return (int) (lo % MOD);
}
private int gcd(int x, int y) {
    return y == 0 ? x : gcd(y, x % y);
}
